```perl
## [:< ## name = threshold-checker
## [:< ## descr = reads threshold from config and logs warning if value exceeds it
## [:< ## category = monitoring
## [:< ## author = protocol-7

package zenka.monitor.threshold;

use strict;
use warnings;

sub init_code {
    # load config and log modules
    perlmod.load qw| config base.logs |;
}

sub check_threshold {
    my ( $value, $name ) = @ARG;

    # read threshold from config with default of 30
    my $threshold = 30;
    if ( exists $ENV{CONFIG} ) {
        my $config = config.read( $ENV{CONFIG} );
        if ( defined $config->{ threshold } ) {
            $threshold = $config->{ threshold };
        }
    }

    # compare value against threshold
    if ( $value > $threshold ) {
        # log warning if value exceeds threshold
        base.logs->( 0, "WARNING: value %s (%d) exceeds threshold (%d)\n", $name, $value, $threshold );
        return { mode => qw| false |, data => "threshold exceeded" };
    }

    return { mode => qw| true |, data => "within threshold" };
}

1;
```

**Usage example:**

```perl
# caller code
my $result = $code{'zenka.monitor.threshold'}->check_threshold( 42, "cpu_usage" );
if ( $result->{ mode } eq qw| false | ) {
    print $result->{ data } . "\n";
}
```

**Key design decisions:**
- **Default of 30** is used if config isn't found or doesn't contain `threshold`
- **Warning level (0)** is used since exceeding a threshold is a warning condition
- **Dot notation** (`$ENV{CONFIG}` style config access) matches P7 conventions
- **Returns a hashref** with `mode` and `data` fields for consistent error reporting
